import * as React from 'react'
import {
  CandlestickChart as CandlestickSeries,
  BarChart as BarSeries,
  LineChart as LineSeries,
} from 'echarts/charts'
import {
  GridComponent,
  TooltipComponent,
  LegendComponent,
  AxisPointerComponent,
} from 'echarts/components'
import {
  Chart,
  ChartCanvas,
  ChartLegend,
  ChartDataTable,
  useChart,
  mergeChartOptions,
  registerChartModules,
  type ChartProps,
  type EChartsOption,
  type ChartHandle,
} from '@/components/ui/chart'
import { Button } from '@/components/ui/button'
registerChartModules([
  CandlestickSeries,
  BarSeries,
  LineSeries,
  GridComponent,
  TooltipComponent,
  LegendComponent,
  AxisPointerComponent,
])
export interface CandlestickDatum {
  id: string
  date: string
  open: number
  close: number
  low: number
  high: number
  volume?: number
}
export interface CandlestickSelection {
  indices: number[]
  rows: CandlestickDatum[]
}
/**
 * Computes trailing simple averages of closing prices with null warm-up entries. Requires a positive integer period and finite closing prices.
 */
export function calculateMovingAverage(
  data: readonly CandlestickDatum[],
  period: number,
): (number | null)[] {
  if (!Number.isInteger(period) || period < 1)
    throw new Error('Moving-average periods must be positive integers.')
  if (data.some((row) => !Number.isFinite(row.close)))
    throw new Error('Closing prices must be finite.')
  let sum = 0
  return data.map((row, index) => {
    sum += row.close
    if (index >= period) sum -= data[index - period].close
    return index < period - 1 ? null : sum / period
  })
}
export interface CandlestickChartProps extends Omit<ChartProps, 'option'> {
  data: CandlestickDatum[]
  movingAverages?: readonly number[]
  showVolume?: boolean
  zoom?: boolean
  brush?: boolean
  onSelectionChange?: (selection: CandlestickSelection) => void
  upColor?: string
  downColor?: string
  showLegend?: boolean
  showTooltip?: boolean
  showDataTable?: boolean
  option?: EChartsOption
}
const defaultAverages = [5, 10, 20]
/**
 * Offers pointer-brush activation and keyboard-accessible date-range selection. Applies or clears brush actions on the current chart instance.
 */
export function CandlestickChartControls({
  data,
  selection,
  ready = true,
}: {
  data: CandlestickDatum[]
  selection: CandlestickSelection
  ready?: boolean
}): React.JSX.Element {
  const { instance } = useChart(),
    [drawing, setDrawing] = React.useState(false),
    [start, setStart] = React.useState(0),
    [end, setEnd] = React.useState(Math.max(0, data.length - 1))
  React.useEffect(() => {
    setStart(0)
    setEnd(Math.max(0, data.length - 1))
  }, [data.length])
  const currentEngine = instance.current
  React.useEffect(() => setDrawing(false), [currentEngine])
  React.useEffect(() => {
    if (selection.indices.length) {
      setStart(selection.indices[0])
      setEnd(selection.indices[selection.indices.length - 1])
    }
  }, [selection.indices])
  const from = Math.min(start, Math.max(0, data.length - 1)),
    to = Math.max(from, Math.min(end, Math.max(0, data.length - 1)))
  return (
    <div className="flex flex-wrap items-center gap-2 text-xs">
      <Button
        size="sm"
        variant={drawing ? 'default' : 'outline'}
        aria-pressed={drawing}
        disabled={!ready || !data.length}
        onClick={() => {
          instance.current?.dispatchAction({
            type: 'takeGlobalCursor',
            key: 'brush',
            brushOption: { brushType: drawing ? false : 'lineX', brushMode: 'single' },
          })
          setDrawing(!drawing)
        }}
      >
        Brush range
      </Button>
      <label className="flex items-center gap-1">
        From
        <select
          aria-label="Selection start"
          className="h-8 max-w-36 rounded border bg-background px-2"
          value={from}
          disabled={!data.length}
          onChange={(e) => {
            const next = Number(e.target.value)
            setStart(next)
            setEnd(Math.max(next, to))
          }}
        >
          {data.map((d, i) => (
            <option key={d.id} value={i}>
              {d.date}
            </option>
          ))}
        </select>
      </label>
      <label className="flex items-center gap-1">
        To
        <select
          aria-label="Selection end"
          className="h-8 max-w-36 rounded border bg-background px-2"
          value={to}
          disabled={!data.length}
          onChange={(e) => setEnd(Number(e.target.value))}
        >
          {data.map((d, i) => (
            <option key={d.id} value={i} disabled={i < from}>
              {d.date}
            </option>
          ))}
        </select>
      </label>
      <Button
        size="sm"
        variant="outline"
        disabled={!ready || !data.length}
        onClick={() =>
          instance.current?.dispatchAction({
            type: 'brush',
            areas: [{ brushType: 'lineX', xAxisIndex: 0, coordRange: [from, to] }],
          })
        }
      >
        Apply range
      </Button>
      <Button
        size="sm"
        variant="ghost"
        disabled={!ready}
        onClick={() => {
          instance.current?.dispatchAction({ type: 'brush', areas: [] })
          instance.current?.dispatchAction({
            type: 'takeGlobalCursor',
            key: 'brush',
            brushOption: { brushType: false },
          })
          setDrawing(false)
        }}
      >
        Clear selection
      </Button>
      <span role="status" aria-live="polite">
        {selection.rows.length} selected
      </span>
    </div>
  )
}
/**
 * Displays validated OHLC observations with optional moving averages, linked volume and zoom, and typed brush-selection callbacks.
 */
export function CandlestickChart({
  data,
  movingAverages = defaultAverages,
  showVolume = true,
  zoom = true,
  brush = true,
  onSelectionChange,
  upColor = '#16956d',
  downColor = '#d95454',
  showLegend = true,
  showTooltip = true,
  showDataTable = true,
  option,
  children,
  ...props
}: CandlestickChartProps): React.JSX.Element {
  const [instance, setInstance] = React.useState<ReturnType<ChartHandle['getInstance']>>(null),
    [selection, setSelection] = React.useState<CandlestickSelection>({ indices: [], rows: [] })
  const brushAreas = React.useRef<unknown[]>([])
  const previousSelection = React.useRef<string>('[]')
  const invalid = data.some(
    (d) =>
      ![d.open, d.close, d.low, d.high].every(Number.isFinite) ||
      d.low > Math.min(d.open, d.close) ||
      d.high < Math.max(d.open, d.close) ||
      d.low > d.high ||
      (d.volume !== undefined && (!Number.isFinite(d.volume) || d.volume < 0)),
  )
    ? 'Candles need valid OHLC bounds and nonnegative volume.'
    : movingAverages.some((p) => !Number.isInteger(p) || p < 1) ||
        new Set(movingAverages).size !== movingAverages.length
      ? 'Moving-average periods must be unique positive integers.'
      : new Set(data.map((d) => d.id)).size !== data.length ||
          new Set(data.map((d) => d.date)).size !== data.length
        ? 'Candle IDs and date labels must be unique.'
        : undefined
  const built = React.useMemo<EChartsOption>(
    () =>
      invalid
        ? {}
        : {
            grid: [
              {
                left: 12,
                right: 24,
                top: 20,
                bottom: showVolume ? '36%' : zoom ? 64 : 28,
                containLabel: true,
              },
              ...(showVolume
                ? [{ left: 12, right: 24, top: '68%', bottom: zoom ? 64 : 28, containLabel: true }]
                : []),
            ],
            tooltip: { show: showTooltip, trigger: 'axis', axisPointer: { type: 'cross' } },
            axisPointer: { link: [{ xAxisIndex: 'all' }] },
            legend: { show: false, data: ['Price', ...movingAverages.map((p) => `MA ${p}`)] },
            xAxis: [
              {
                type: 'category',
                data: data.map((d) => d.date),
                axisLabel: { show: !showVolume, hideOverlap: true },
                axisTick: { show: false },
              },
              ...(showVolume
                ? [
                    {
                      type: 'category' as const,
                      gridIndex: 1,
                      data: data.map((d) => d.date),
                      axisTick: { show: false },
                      axisLabel: { hideOverlap: true },
                    },
                  ]
                : []),
            ],
            yAxis: [
              {
                type: 'value',
                scale: true,
                splitLine: { lineStyle: { type: 'dashed', opacity: 0.25 } },
              },
              ...(showVolume
                ? [
                    {
                      type: 'value' as const,
                      gridIndex: 1,
                      scale: true,
                      splitNumber: 2,
                      splitLine: { show: false },
                      axisLabel: {
                        hideOverlap: true,
                        formatter: (value: number) =>
                          new Intl.NumberFormat('en', { notation: 'compact' }).format(value),
                      },
                    },
                  ]
                : []),
            ],
            ...(zoom
              ? {
                  dataZoom: [
                    { type: 'inside', xAxisIndex: showVolume ? [0, 1] : [0] },
                    {
                      type: 'slider',
                      xAxisIndex: showVolume ? [0, 1] : [0],
                      height: 20,
                      bottom: 8,
                    },
                  ],
                }
              : {}),
            ...(brush
              ? {
                  brush: {
                    xAxisIndex: showVolume ? [0, 1] : [0],
                    brushLink: 'all',
                    brushMode: 'single',
                    outOfBrush: { colorAlpha: 0.15 },
                    throttleType: 'debounce',
                    throttleDelay: 80,
                  },
                }
              : {}),
            series: [
              {
                id: 'price',
                name: 'Price',
                type: 'candlestick',
                barMaxWidth: 18,
                data: data.map((d) => ({
                  id: d.id,
                  name: d.date,
                  value: [d.open, d.close, d.low, d.high],
                })),
                itemStyle: {
                  color: upColor,
                  color0: downColor,
                  borderColor: upColor,
                  borderColor0: downColor,
                },
              },
              ...movingAverages.map((p) => ({
                id: `ma-${p}`,
                name: `MA ${p}`,
                type: 'line' as const,
                data: calculateMovingAverage(data, p),
                showSymbol: false,
                smooth: true,
                lineStyle: { width: 1.5 },
              })),
              ...(showVolume
                ? [
                    {
                      id: 'volume',
                      name: 'Volume',
                      type: 'bar' as const,
                      xAxisIndex: 1,
                      yAxisIndex: 1,
                      data: data.map((d) => ({
                        id: d.id,
                        value: d.volume ?? 0,
                        itemStyle: {
                          color: d.close >= d.open ? upColor : downColor,
                          opacity: 0.55,
                        },
                      })),
                    },
                  ]
                : []),
            ],
          },
    [invalid, data, movingAverages, showVolume, showTooltip, zoom, brush, upColor, downColor],
  )
  const chartOption = React.useMemo(() => mergeChartOptions(built, option), [built, option])
  return (
    <Chart
      empty={!data.length}
      {...props}
      error={props.error ?? invalid}
      features={{
        ...props.features,
        dataZoom: zoom || props.features?.dataZoom,
        brush: brush || props.features?.brush,
      }}
      onReady={(chart) => {
        if (brush && brushAreas.current.length)
          chart.dispatchAction({ type: 'brush', areas: brushAreas.current })
        setInstance(chart)
        props.onReady?.(chart)
      }}
      events={{
        ...props.events,
        brushselected: (event, chart) => {
          brushAreas.current = (event.batch[0]?.areas ?? []).flatMap((value) => {
            if (
              !value ||
              typeof value !== 'object' ||
              !('coordRange' in value) ||
              !Array.isArray(value.coordRange)
            )
              return []
            // Panel IDs belong to one engine instance; retain only data coordinates.
            return [{ brushType: 'lineX', xAxisIndex: 0, coordRange: value.coordRange }]
          })
          const indices = [
            ...new Set(
              event.batch.flatMap((batch) =>
                batch.selected.filter((s) => s.seriesIndex === 0).flatMap((s) => s.dataIndex),
              ),
            ),
          ]
            .filter((i) => i >= 0 && i < data.length)
            .sort((a, b) => a - b)
          const next = { indices, rows: indices.map((i) => data[i]) }
          setSelection(next)
          const key = JSON.stringify(next.rows.map((row, index) => [next.indices[index], row.id]))
          if (key !== previousSelection.current) {
            previousSelection.current = key
            onSelectionChange?.(next)
          }
          props.events?.brushselected?.(event, chart)
        },
      }}
      option={chartOption}
    >
      {children ?? (
        <>
          <ChartCanvas />
          {showLegend && (
            <ChartLegend
              items={[
                { name: 'Price', color: upColor },
                ...movingAverages.map((p) => ({ name: `MA ${p}` })),
              ]}
            />
          )}
          {brush && (
            <CandlestickChartControls
              data={data}
              selection={selection}
              ready={Boolean(instance) && !invalid}
            />
          )}
          {showDataTable && (
            <ChartDataTable
              columns={['Date', 'Open', 'Close', 'Low', 'High', ...(showVolume ? ['Volume'] : [])]}
              rows={data.map((d) => ({
                id: d.id,
                cells: [
                  d.date,
                  d.open,
                  d.close,
                  d.low,
                  d.high,
                  ...(showVolume ? [d.volume ?? 0] : []),
                ],
              }))}
            />
          )}
        </>
      )}
    </Chart>
  )
}

import * as React from 'react'
import * as echarts from 'echarts/core'
import type { EChartsOption, ECElementEvent, SetOptionOpts } from 'echarts'
import { AriaComponent } from 'echarts/components'
import { SVGRenderer } from 'echarts/renderers'
import { cn } from '@/lib/utils'

echarts.use([AriaComponent, SVGRenderer])

export { use as registerChartModules } from 'echarts/core'
export type { EChartsOption, ECElementEvent } from 'echarts'
export type ChartModule = Extract<Parameters<typeof echarts.use>[0], unknown[]>[number]
export interface ChartFeatures {
  dataZoom?: boolean
  brush?: boolean
}
export interface ChartBrushEvent {
  batch: { areas?: unknown[]; selected: { seriesIndex: number; dataIndex: number[] }[] }[]
}
export const chartPalette = ['#b93e28', '#5579bd', '#36836a', '#c38a28', '#9864af', '#2992a6']
export interface ChartLegendEvent {
  name: string
  selected: Record<string, boolean>
}
export interface ChartZoomEvent {
  type: string
  start?: number
  end?: number
  batch?: { start: number; end: number }[]
}
export interface ChartEvents {
  brushselected?: (event: ChartBrushEvent, instance: echarts.EChartsType) => void
  selectchanged?: (event: echarts.SelectChangedEvent, instance: echarts.EChartsType) => void
  georoam?: (
    event: { zoom?: number; dx?: number; dy?: number },
    instance: echarts.EChartsType,
  ) => void
  click?: (event: ECElementEvent, instance: echarts.EChartsType) => void
  dblclick?: (event: ECElementEvent, instance: echarts.EChartsType) => void
  legendselectchanged?: (event: ChartLegendEvent, instance: echarts.EChartsType) => void
  datazoom?: (event: ChartZoomEvent, instance: echarts.EChartsType) => void
  finished?: (event: unknown, instance: echarts.EChartsType) => void
}
export interface ChartHandle {
  getInstance: () => echarts.EChartsType | null
  resize: () => void
  dispatchAction: (action: Parameters<echarts.EChartsType['dispatchAction']>[0]) => void
  getDataURL: (options?: Parameters<echarts.EChartsType['getDataURL']>[0]) => string | undefined
}
export interface ChartProps extends Omit<React.ComponentProps<'figure'>, 'onError' | 'ref'> {
  option: EChartsOption
  modules?: readonly ChartModule[]
  features?: ChartFeatures
  label: string
  height?: React.CSSProperties['height']
  renderer?: 'svg' | 'canvas'
  theme?: 'auto' | 'light' | 'dark'
  palette?: string[]
  animated?: boolean
  loading?: boolean
  empty?: boolean
  error?: string
  emptyMessage?: React.ReactNode
  events?: ChartEvents
  updateOptions?: SetOptionOpts
  onReady?: (instance: echarts.EChartsType) => void
  onError?: (error: Error) => void
  ref?: React.Ref<ChartHandle>
}
interface ChartContextValue extends Omit<ChartProps, 'ref' | 'children' | 'theme' | 'palette'> {
  instance: React.RefObject<echarts.EChartsType | null>
  mode: 'light' | 'dark'
  colors: string[]
  selected: Record<string, boolean>
  setSelected: React.Dispatch<React.SetStateAction<Record<string, boolean>>>
}
const ChartContext = React.createContext<ChartContextValue | null>(null)
export function useChart() {
  const context = React.useContext(ChartContext)
  if (!context) throw new Error('Chart parts must be used inside Chart.')
  return context
}
/**
 * Returns a deep-merged copy of the base options. Neither the base object nor its nested options are mutated.
 */
export function mergeChartOptions(base: EChartsOption, overrides?: EChartsOption): EChartsOption {
  return echarts.util.merge(echarts.util.clone(base), overrides ?? {}, true)
}

/**
 * Provides shared chart options, theme and motion handling, events, and the imperative chart handle for composable visualization parts.
 */
export function Chart({
  option,
  modules,
  features,
  label,
  height = 320,
  renderer = 'svg',
  theme = 'auto',
  palette,
  animated,
  loading = false,
  empty = false,
  error,
  emptyMessage = 'No data to display',
  events,
  updateOptions,
  onReady,
  onError,
  children,
  className,
  style,
  ref,
  ...props
}: ChartProps) {
  const root = React.useRef<HTMLElement>(null)
  const instance = React.useRef<echarts.EChartsType | null>(null)
  const [mode, setMode] = React.useState<'light' | 'dark'>('light')
  const [reduced, setReduced] = React.useState(false)
  const [accent, setAccent] = React.useState(chartPalette[0])
  const [fontFamily, setFontFamily] = React.useState('sans-serif')
  const [selected, setSelected] = React.useState<Record<string, boolean>>({})
  React.useEffect(() => {
    const media = window.matchMedia('(prefers-reduced-motion: reduce)')
    const read = () => {
      const node = root.current
      if (!node) return
      setMode(
        theme === 'auto' ? (node.closest('.dark, [data-theme="dark"]') ? 'dark' : 'light') : theme,
      )
      setReduced(media.matches && !node.closest('[data-preview-motion="full"]'))
      const computed = getComputedStyle(node)
      setFontFamily(computed.fontFamily || 'sans-serif')
      const color = computed.getPropertyValue('--primary').trim()
      setAccent(/^#|^rgb|^hsl/.test(color) ? color : chartPalette[0])
    }
    read()
    const observer = new MutationObserver(read)
    let node: HTMLElement | null = root.current
    while (node) {
      observer.observe(node, {
        attributes: true,
        attributeFilter: ['class', 'style', 'data-theme', 'data-preview-motion'],
      })
      node = node.parentElement
    }
    media.addEventListener('change', read)
    return () => {
      observer.disconnect()
      media.removeEventListener('change', read)
    }
  }, [theme])
  React.useImperativeHandle(
    ref,
    () => ({
      getInstance: () => instance.current,
      resize: () => instance.current?.resize(),
      dispatchAction: (action) => {
        instance.current?.dispatchAction(action)
      },
      getDataURL: (options) => instance.current?.getDataURL(options),
    }),
    [],
  )
  const colors = React.useMemo(
    () => (palette?.length ? palette : [accent, ...chartPalette.slice(1)]),
    [palette, accent],
  )
  const themedOption = React.useMemo(() => {
    const result = mergeChartOptions(
      {
        backgroundColor: 'transparent',
        color: colors,
        textStyle: { fontFamily, fontSize: 12 },
        ...(option.tooltip ? { tooltip: { confine: true, renderMode: 'richText' as const } } : {}),
        aria: { enabled: true, label: { description: label } },
      },
      option,
    )
    result.animation = animated ?? option.animation ?? !reduced
    if (Object.keys(selected).length) {
      const legends = Array.isArray(result.legend) ? result.legend : [result.legend ?? {}]
      result.legend = legends.map((legend) => ({
        ...legend,
        selected: { ...legend.selected, ...selected },
      }))
    }
    return result
  }, [option, colors, label, animated, reduced, selected, fontFamily])
  return (
    <ChartContext.Provider
      value={{
        option: themedOption,
        modules,
        features,
        label,
        height,
        renderer,
        mode,
        colors,
        selected,
        setSelected,
        instance,
        animated,
        loading,
        empty,
        error,
        emptyMessage,
        events,
        updateOptions,
        onReady,
        onError,
      }}
    >
      <figure
        ref={root}
        data-slot="chart"
        aria-label={label}
        className={cn(
          'w-full min-w-0 space-y-4 rounded-lg bg-background text-foreground',
          className,
        )}
        style={{
          ...(theme !== 'auto'
            ? ({
                '--background': mode === 'dark' ? '#202321' : '#ffffff',
                '--foreground': mode === 'dark' ? '#eeeeea' : '#262725',
                '--muted-foreground': mode === 'dark' ? '#a2a79e' : '#62695e',
                '--border': mode === 'dark' ? '#343a32' : '#e9e9e3',
                colorScheme: mode,
              } as React.CSSProperties)
            : {}),
          ...style,
        }}
        {...props}
      >
        {children ?? <ChartCanvas />}
      </figure>
    </ChartContext.Provider>
  )
}

/**
 * Creates and disposes the native ECharts instance, loads optional rendering features, and renders loading, empty, and recoverable error states.
 */
export function ChartCanvas({ className, style, ...props }: React.ComponentProps<'div'>) {
  const context = useChart()
  const latest = React.useRef(context)
  latest.current = context
  const host = React.useRef<HTMLDivElement>(null)
  const applied = React.useRef<EChartsOption | null>(null)
  const [failure, setFailure] = React.useState<string>()
  const [preparing, setPreparing] = React.useState(false)
  React.useEffect(() => {
    const node = host.current
    if (!node) return
    let chart: echarts.EChartsType | undefined
    let cancelled = false
    const fail = (reason: unknown) => {
      if (cancelled) return
      const error = reason instanceof Error ? reason : new Error(String(reason))
      setFailure(error.message)
      latest.current.onError?.(error)
      setPreparing(false)
    }
    let resize: ResizeObserver | undefined
    const initialize = () => {
      if (cancelled) return
      try {
        if (latest.current.modules?.length) echarts.use([...latest.current.modules])
        chart = echarts.init(node, context.mode, { renderer: context.renderer })
        context.instance.current = chart
        for (const event of [
          'click',
          'dblclick',
          'legendselectchanged',
          'datazoom',
          'finished',
          'brushselected',
          'selectchanged',
          'georoam',
        ] as const) {
          chart.on(event, (...args: unknown[]) => {
            const payload = args[0]
            if (event === 'legendselectchanged')
              latest.current.setSelected((payload as ChartLegendEvent).selected)
            const handler = latest.current.events?.[event] as
              ((value: unknown, instance: echarts.EChartsType) => void) | undefined
            if (chart) handler?.(payload, chart)
          })
        }
        chart.setOption(latest.current.option, {
          replaceMerge: ['series'],
          ...latest.current.updateOptions,
        })
        applied.current = latest.current.option
        resize = new ResizeObserver(() => {
          if (!chart?.isDisposed()) chart?.resize()
        })
        resize.observe(node)
        latest.current.onReady?.(chart)
        setFailure(undefined)
        setPreparing(false)
      } catch (reason) {
        fail(reason)
      }
    }
    const pending: Promise<void>[] = []
    if (context.renderer === 'canvas')
      pending.push(
        import('@/components/ui/chart-canvas-renderer').then(({ CanvasRenderer }) => {
          echarts.use(CanvasRenderer)
        }),
      )
    if (context.features?.dataZoom)
      pending.push(
        import('@/components/ui/chart-zoom').then(({ DataZoomComponent }) => {
          echarts.use(DataZoomComponent)
        }),
      )
    if (context.features?.brush)
      pending.push(
        import('@/components/ui/chart-brush').then(({ BrushComponent }) => {
          echarts.use(BrushComponent)
        }),
      )
    if (pending.length) {
      setPreparing(true)
      Promise.all(pending).then(initialize, fail)
    } else initialize()
    return () => {
      cancelled = true
      resize?.disconnect()
      chart?.dispose()
      if (context.instance.current === chart) context.instance.current = null
      applied.current = null
    }
  }, [
    context.renderer,
    context.mode,
    context.instance,
    context.features?.dataZoom,
    context.features?.brush,
  ])
  React.useEffect(() => {
    const chart = context.instance.current
    if (!chart || chart.isDisposed()) return
    if (context.modules?.length) echarts.use([...context.modules])
    if (applied.current === context.option) return
    try {
      chart.setOption(context.option, { replaceMerge: ['series'], ...context.updateOptions })
      applied.current = context.option
      setFailure(undefined)
    } catch (reason) {
      const error = reason instanceof Error ? reason : new Error(String(reason))
      setFailure(error.message)
      context.onError?.(error)
    }
  }, [context.option, context.modules, context.updateOptions, context.instance, context.onError])
  const message = context.error ?? failure
  return (
    <div
      data-slot="chart-canvas"
      className={cn('relative min-w-0', className)}
      style={{ height: context.height, ...style }}
      aria-busy={context.loading || preparing}
      {...props}
    >
      <div
        ref={host}
        // ECharts positions text in physical coordinates, including on RTL pages.
        dir="ltr"
        role="img"
        aria-label={context.label}
        className="h-full w-full"
        style={{ visibility: message || context.empty ? 'hidden' : undefined }}
      />
      {(context.loading || preparing || context.empty || message) && (
        <div
          role={message ? 'alert' : 'status'}
          className="absolute inset-0 flex items-center justify-center gap-3 rounded-lg bg-background/90 p-6 text-center text-sm text-muted-foreground"
        >
          {message ??
            (context.loading || preparing ? (
              <>
                <span
                  className="size-4 animate-spin rounded-full border-2 border-current border-t-transparent motion-reduce:animate-none"
                  aria-hidden="true"
                />
                Loading chart…
              </>
            ) : (
              context.emptyMessage
            ))}
        </div>
      )}
    </div>
  )
}
